import { Buffer } from "node:buffer";
export default async function download(_input, context) {
  const r = await context.fetch("https://n8n.io/n8n-logo.png");
  if (!r.ok) throw Error("Attachment download failed; inspect the Outlook draft");
  const bytes = new Uint8Array(await r.arrayBuffer());
  if (!bytes.length) throw Error("Empty attachment; inspect the Outlook draft");
  return {
    name: "n8n.png",
    mimeType: "image/png",
    contentBase64: Buffer.from(bytes).toString("base64"),
  };
}

